//
//  GoldenHebrewCalendarTests.swift
//  KosherSwiftTests
//
//  Cross-checks the JewishCalendar, TefilaRules and HebrewDateFormatter against values generated by KosherJava itself (see
//  tools/golden/HebrewGoldenGenerator.java): every day from 2024 to 2027 and every third day from 1981 to 2100, in and out
//  of Israel.
//

import Foundation
import XCTest
@testable import KosherSwift

final class GoldenHebrewCalendarTests: XCTestCase {

    static func string(_ date: Date?) -> String {
        guard let date = date else {
            return "null"
        }
        return String(format: "%.3f", date.timeIntervalSince1970)
    }

    /// KosherJava's "I<seconds>.<nanoseconds>" as seconds with millisecond precision, like ``string(_:)``.
    static func instant(_ value: Substring) -> String {
        if value == "null" {
            return "null"
        }
        let parts = value.dropFirst().split(separator: ".")
        let seconds = Double(Int64(parts[0])!) + Double(Int64(parts[1])!) / 1_000_000_000
        return String(format: "%.3f", seconds)
    }

    static func daf(_ daf: Daf?) -> String {
        guard let daf = daf else {
            return "null"
        }
        return "\(daf.getMasechtaNumber()):\(daf.getDaf())"
    }

