    static let rules = TefilaRules()

    static func formatted(_ formatter: HebrewDateFormatter, _ name: String, _ jc: JewishCalendar) -> String {
        switch name {
        case "format": return formatter.format(jewishCalendar: jc)
        case "formatYomTov": return formatter.formatYomTov(jewishCalendar: jc)
        case "formatRoshChodesh": return formatter.formatRoshChodesh(jewishCalendar: jc)
        case "formatParshah": return formatter.formatParshah(jewishCalendar: jc)
        case "formatSpecialParshah": return formatter.formatSpecialParshah(jewishCalendar: jc)
        case "formatOmer": return formatter.formatOmer(jewishCalendar: jc)
        case "formatDayOfWeek": return formatter.formatDayOfWeek(jewishCalendar: jc)
        case "formatMonth": return formatter.formatMonth(jewishCalendar: jc)
        case "formatDafYomiBavli": return jc.getDafYomiBavli().map { formatter.formatDafYomiBavli(daf: $0) } ?? "null"
        case "formatDafYomiYerushalmi": return jc.getDafYomiYerushalmi().map { formatter.formatDafYomiYerushalmi(daf: $0) } ?? "null"
        default: return "unknown formatter method \(name)"
        }
    }

    func testJewishCalendarMatchesKosherJava() throws {
        let hebrew = HebrewDateFormatter()
        hebrew.hebrewFormat = true
        let english = HebrewDateFormatter()
        var header: [Substring] = []
        var failures: [String: [String]] = [:]
        var compared = 0
        for line in try GoldenZmanimTests.readLines("hebrew.tsv.gz") {
            let f = line.split(separator: "\t", omittingEmptySubsequences: false)
            if f[0] == "#H" {
                header = f
                continue
            }
            if f[0] == "N" {
                compared += 1
                let actual = hebrew.formatHebrewNumber(number: Int(f[1])!)
                if actual != f[2] {
                    failures["formatHebrewNumber", default: []].append("\(f[1]): expected \(f[2]), got \(actual)")
                }
                continue
            }
            #if os(Linux)
            // swift-corelibs-foundation's Hebrew calendar (its bundled ICU) is a day off for all of the year 5806
            // (September 2045 to September 2046); Apple's Foundation is correct
            if f[1] >= "2045-08-01" && f[1] <= "2046-12-31" { // with a margin for methods that look at nearby days
                continue
            }
            #endif
            let jc = JewishCalendar(localDate: GoldenZmanimTests.localDate(f[1]), inIsrael: f[2] == "1", useModernHolidays: f[2] == "1")
            for i in 3..<f.count {
                let name = String(header[i])
                let expected = name.hasPrefix("getMolad") && !name.hasPrefix("getMolad.") || name.contains("KidushLevana")
                    ? GoldenHebrewCalendarTests.instant(f[i]) : String(f[i])
                let actual: String
                if name.hasPrefix("he.") || name.hasPrefix("en.") {
                    actual = GoldenHebrewCalendarTests.formatted(name.hasPrefix("he.") ? hebrew : english, String(name.dropFirst(3)), jc)
                } else if let method = GoldenHebrewCalendarTests.methods[name] {
                    actual = method(jc)
                } else {
                    failures[name, default: []].append("not available in KosherSwift")
                    continue
                }
                compared += 1
                if actual != expected {
                    failures[name, default: []].append("\(f[1]) \(f[2] == "1" ? "Israel" : "diaspora"): expected \(expected), got \(actual)")
                }
            }
        }
        let summary = failures.keys.sorted().map { "\($0): \(failures[$0]!.count) differences, for example \(failures[$0]!.prefix(3).joined(separator: "; "))" }
        print("Compared \(compared) Hebrew calendar values with KosherJava, \(failures.values.map { $0.count }.reduce(0, +)) differences")
        XCTAssertGreaterThan(compared, 1_000_000)
        XCTAssertTrue(failures.isEmpty, "\n" + summary.joined(separator: "\n"))
    }
}
